/// Count how many times `val` occurs in `nums`.
#[verifier::spec]
fn count_eq(nums: &Vec<i8>, val: i8) -> nat {
    (0..nums.len()).filter(|&i| nums[i] == val).count()
}

/// The predicate under which we should answer "YES".
#[verifier::spec]
fn yes_predicate(nums: &Vec<i8>) -> bool {
    // note: input length is always 3 (we require that below)
    // so `count_eq(nums, 3) == 3` really means all three are 3.
    nums.iter().any(|&x| x == 1)
        || count_eq(nums, 2) >= 2
        || (count_eq(nums, 2) >= 1 && count_eq(nums, 4) >= 2)
        || count_eq(nums, 3) == 3
}

